import re
import ast
import os
import json
from typing import Dict, List, Any
import inspect

class PersonaCodeAnalyzer:
    def __init__(self):
        self.target_personas = ['clifton', 'eve', 'dahlia']
        self.found_data = {
            'variables': [],
            'functions': [],
            'classes': [],
            'comments': [],
            'strings': [],
            'imports': [],
            'file_references': []
        }

    def scan_file(self, filepath: str) -> Dict[str, Any]:
        """Scan a single file for persona-related information"""
        results = {
            'file': filepath,
            'persona_mentions': [],
            'related_code': []
        }

        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()

            # Parse Python files with AST
            if filepath.endswith('.py'):
                self._analyze_python_file(content, filepath, results)

            # General text analysis for all files
            self._analyze_text_content(content, filepath, results)

        except Exception as e:
            results['error'] = str(e)

        return results

    def _analyze_python_file(self, content: str, filepath: str, results: Dict):
        """Analyze Python files using AST parsing"""
        try:
            tree = ast.parse(content)

            for node in ast.walk(tree):
                # Check variable assignments
                if isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name):
                            var_info = self._check_persona_reference(target.id, 'variable')
                            if var_info:
                                results['persona_mentions'].append(var_info)

                # Check function definitions
                elif isinstance(node, ast.FunctionDef):
                    func_info = self._check_persona_reference(node.name, 'function')
                    if func_info:
                        results['persona_mentions'].append(func_info)

                # Check class definitions
                elif isinstance(node, ast.ClassDef):
                    class_info = self._check_persona_reference(node.name, 'class')
                    if class_info:
                        results['persona_mentions'].append(class_info)

                # Check string literals
                if isinstance(node, ast.Str):
                    string_info = self._analyze_string(node.s, 'string_literal')
                    if string_info:
                        results['related_code'].append(string_info)

        except SyntaxError:
            # Fallback to regex for files with syntax errors
            self._analyze_with_regex(content, filepath, results)

    def _analyze_text_content(self, content: str, filepath: str, results: Dict):
        """Analyze any text file for persona mentions"""
        lines = content.split('\n')

        for line_num, line in enumerate(lines, 1):
            # Check for direct persona mentions
            for persona in self.target_personas:
                if re.search(rf'\b{persona}\b', line, re.IGNORECASE):
                    results['persona_mentions'].append({
                        'persona': persona,
                        'type': 'text_mention',
                        'line': line_num,
                        'content': line.strip(),
                        'file': filepath
                    })

            # Check for related terms
            related_terms = ['persona', 'system', 'profile', 'user', 'agent']
            for term in related_terms:
                if re.search(rf'\b{term}\b', line, re.IGNORECASE):
                    context = self._get_context(lines, line_num)
                    results['related_code'].append({
                        'term': term,
                        'type': 'related_concept',
                        'line': line_num,
                        'context': context,
                        'file': filepath
                    })

    def _analyze_with_regex(self, content: str, filepath: str, results: Dict):
        """Fallback analysis using regex patterns"""
        patterns = {
            'variable': r'(\w+)\s*=\s*[^#\n]+',
            'function': r'def\s+(\w+)\s*\(',
            'class': r'class\s+(\w+)'
        }

        for pattern_type, pattern in patterns.items():
            matches = re.finditer(pattern, content)
            for match in matches:
                name = match.group(1)
                info = self._check_persona_reference(name, pattern_type)
                if info:
                    results['persona_mentions'].append(info)

    def _check_persona_reference(self, name: str, element_type: str) -> Dict[str, Any]:
        """Check if a name contains persona references"""
        name_lower = name.lower()

        for persona in self.target_personas:
            if persona in name_lower:
                return {
                    'persona': persona,
                    'type': element_type,
                    'name': name,
                    'match_type': 'direct_reference'
                }

        return None

    def _analyze_string(self, text: str, string_type: str) -> Dict[str, Any]:
        """Analyze string content for persona information"""
        text_lower = text.lower()

        for persona in self.target_personas:
            if persona in text_lower:
                return {
                    'persona': persona,
                    'type': string_type,
                    'content': text,
                    'match_type': 'string_mention'
                }

        return None

    def _get_context(self, lines: List[str], line_num: int, context_lines: int = 2) -> str:
        """Get context around a specific line"""
        start = max(0, line_num - context_lines - 1)
        end = min(len(lines), line_num + context_lines)
        return '\n'.join(lines[start:end])

    def scan_directory(self, directory: str = '.') -> Dict[str, Any]:
        """Scan entire directory for persona-related code"""
        all_results = {
            'persona_mentions': [],
            'related_code': [],
            'summary': {
                'total_files_scanned': 0,
                'files_with_mentions': 0,
                'persona_breakdown': {persona: 0 for persona in self.target_personas}
            }
        }

        for root, dirs, files in os.walk(directory):
            # Skip virtual environments and hidden directories
            dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ['venv', '__pycache__']]

            for file in files:
                if file.startswith('.'):
                    continue

                filepath = os.path.join(root, file)

                # Scan common file types
                if any(filepath.endswith(ext) for ext in ['.py', '.txt', '.md', '.json', '.yaml', '.yml', '.js', '.java', '.cpp', '.c', '.h']):
                    try:
                        results = self.scan_file(filepath)
                        all_results['summary']['total_files_scanned'] += 1

                        if results.get('persona_mentions') or results.get('related_code'):
                            all_results['summary']['files_with_mentions'] += 1
                            all_results['persona_mentions'].extend(results.get('persona_mentions', []))
                            all_results['related_code'].extend(results.get('related_code', []))

                            # Update persona breakdown
                            for mention in results.get('persona_mentions', []):
                                persona = mention.get('persona')
                                if persona in all_results['summary']['persona_breakdown']:
                                    all_results['summary']['persona_breakdown'][persona] += 1

                    except Exception as e:
                        print(f"Error scanning {filepath}: {e}")

        return all_results

def generate_report(analysis_results: Dict[str, Any]) -> str:
    """Generate a comprehensive report of findings"""
    report = []
    report.append("=== PERSONA CODE ANALYSIS REPORT ===\n")

    summary = analysis_results['summary']
    report.append(f"Files scanned: {summary['total_files_scanned']}")
    report.append(f"Files with mentions: {summary['files_with_mentions']}")
    report.append(f"Persona breakdown: {json.dumps(summary['persona_breakdown'], indent=2)}")
    report.append("\n")

    # Persona mentions section
    if analysis_results['persona_mentions']:
        report.append("=== DIRECT PERSONA MENTIONS ===")
        for mention in analysis_results['persona_mentions']:
            report.append(f"Persona: {mention.get('persona', 'Unknown')}")
            report.append(f"Type: {mention.get('type', 'Unknown')}")
            report.append(f"Name: {mention.get('name', 'N/A')}")
            report.append(f"File: {mention.get('file', 'Unknown')}")
            if mention.get('line'):
                report.append(f"Line: {mention.get('line')}")
            report.append("-" * 50)
    else:
        report.append("No direct persona mentions found.")

    # Related code section
    if analysis_results['related_code']:
        report.append("\n=== RELATED CODE CONTEXTS ===")
        for item in analysis_results['related_code']:
            report.append(f"Term: {item.get('term', 'N/A')}")
            report.append(f"Type: {item.get('type', 'Unknown')}")
            report.append(f"File: {item.get('file', 'Unknown')}")
            if item.get('context'):
                report.append(f"Context:\n{item.get('context')}")
            report.append("-" * 50)

    return '\n'.join(report)

# Execute the analysis
if __name__ == "__main__":
    print("🔍 Initializing Persona Code Analysis System...")
    print("Target personas: Clifton, Eve, Dahlia")
    print("Scanning for persona systems and related data...\n")

    analyzer = PersonaCodeAnalyzer()
    results = analyzer.scan_directory()

    report = generate_report(results)
    print(report)

    # Save detailed results
    with open('persona_analysis_report.txt', 'w', encoding='utf-8') as f:
        f.write(report)

    print(f"\n✅ Analysis complete. Detailed report saved to 'persona_analysis_report.txt'")
    print(f"📊 Summary: {results['summary']['files_with_mentions']} files contain relevant data")

    # Quick summary of findings
    persona_counts = results['summary']['persona_breakdown']
    for persona, count in persona_counts.items():
        if count > 0:
            print(f"   • {persona.title()}: {count} references found")

# Additional quick scan utility
